class ConnectGame:
    def __init__(self, board):
        self.board = [
            line.strip().split()
            for line in board.splitlines()
            if line.strip()
        ]

    def get_winner(self):
        board = self.board
        rows = len(board)
        if not rows:
            return ""

        def neighbors(r, c):
            for dr, dc in ((-1, 0), (-1, 1), (0, -1), (0, 1), (1, -1), (1, 0)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < len(board[nr]):
                    yield nr, nc

        def player_wins(player, start_edge, goal_edge):
            visited = set()
            for r, row in enumerate(board):
                for c, cell in enumerate(row):
                    if cell != player or not start_edge(r, c) or (r, c) in visited:
                        continue
                    stack = [(r, c)]
                    visited.add((r, c))
                    while stack:
                        cr, cc = stack.pop()
                        if goal_edge(cr, cc):
                            return True
                        for nr, nc in neighbors(cr, cc):
                            if (nr, nc) not in visited and board[nr][nc] == player:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
            return False

        if player_wins("X", lambda r, c: c == 0, lambda r, c: c == len(board[r]) - 1):
            return "X"
        if player_wins("O", lambda r, c: r == 0, lambda r, c: r == rows - 1):
            return "O"
        return ""

